#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [LinearPowerDensity; 25] = [
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::WattPerMeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MilliwattPerMeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::KilowattPerMeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MegawattPerMeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::GigawattPerMeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::WattPerCentimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MilliwattPerCentimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::KilowattPerCentimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MegawattPerCentimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::GigawattPerCentimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::WattPerMillimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MilliwattPerMillimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::KilowattPerMillimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MegawattPerMillimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::GigawattPerMillimeter),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::WattPerInch),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MilliwattPerInch),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::KilowattPerInch),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MegawattPerInch),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::GigawattPerInch),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::WattPerFoot),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MilliwattPerFoot),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::KilowattPerFoot),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::MegawattPerFoot),
        LinearPowerDensity::const_new(1234.5, LinearPowerDensityUnit::GigawattPerFoot),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(LinearPowerDensityUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            LinearPowerDensity::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in LinearPowerDensityUnit::ALL {
            assert_eq!(
                LinearPowerDensity::const_new(v, unit).as_base().to_bits(),
                LinearPowerDensity::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = LinearPowerDensity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            LinearPowerDensity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in LinearPowerDensityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        LinearPowerDensity::from_base(0.0).auto_unit().unit,
        LinearPowerDensityUnit::WattPerMeter
    );
}

